// Semantic-version precedence and range checker.
const NUMERIC=/(^\d+$)/;
const IDENT=/^[0-9A-Za-z-]+$/;
const NUMERIC_ID=/^(0|[1-9]\d*)$/;
const VERSION=/^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-([0-9A-Za-z.-]+))?(?:\+([0-9A-Za-z.-]+))?$/;

function checkIdentifiers(list){
  for(const id of list){
    if(!IDENT.test(id))throw Error('invalid identifier');
    if(NUMERIC.test(id)&&!NUMERIC_ID.test(id))throw Error('invalid numeric identifier');
  }
}

function parse(v){
  if(typeof v!=='string')throw Error('invalid version');
  const m=VERSION.exec(v);
  if(!m)throw Error('invalid version');
  const prerelease=m[4]===undefined?[]:m[4].split('.');
  const build=m[5]===undefined?[]:m[5].split('.');
  checkIdentifiers(prerelease);
  checkIdentifiers(build);
  return {major:+m[1],minor:+m[2],patch:+m[3],prerelease,build};
}

function isNumericId(id){return NUMERIC.test(id);}

function compareIds(a,b){
  const an=isNumericId(a),bn=isNumericId(b);
  if(an&&bn){
    const d=BigInt(a)-BigInt(b);
    return d<0n?-1:d>0n?1:0;
  }
  if(an)return -1;
  if(bn)return 1;
  return a<b?-1:a>b?1:0;
}

export function compareVersions(a,b){
  const x=parse(a),y=parse(b);
  for(const key of ['major','minor','patch']){
    const d=x[key]-y[key];
    if(d)return d<0?-1:1;
  }
  const lp=x.prerelease,rp=y.prerelease;
  if(lp.length===0&&rp.length===0)return 0;
  if(lp.length===0)return 1;
  if(rp.length===0)return -1;
  const n=Math.min(lp.length,rp.length);
  for(let i=0;i<n;i++){
    const d=compareIds(lp[i],rp[i]);
    if(d)return d;
  }
  if(lp.length!==rp.length)return lp.length<rp.length?-1:1;
  return 0;
}

const OPS=['>=','<=','>','<','='];

function parseComparator(text){
  let op='=';
  for(const o of OPS){
    if(text.startsWith(o)){op=o;text=text.slice(o.length);break;}
  }
  if(text==='')throw Error('invalid comparator');
  return {op,version:parse(text)};
}

function parseRange(range){
  if(typeof range!=='string')throw Error('invalid range');
  const clauses=range.split('||').map(clause=>{
    const parts=clause.trim().split(/\s+/).filter(Boolean);
    if(parts.length===0)throw Error('invalid range');
    return parts.map(parseComparator);
  });
  return clauses;
}

function hasPrerelease(v){return v.prerelease.length>0;}

export function satisfies(version,range){
  const v=parse(version);
  const clauses=parseRange(range);
  for(const comparators of clauses){
    if(!comparators.every(c=>{
      const d=compareVersions(version,c.version);
      return c.op==='='?d===0:c.op==='>'?d>0:c.op==='>='?d>=0:c.op==='<'?d<0:d<=0;
    }))continue;
    if(hasPrerelease(v)){
      const same=comparators.some(c=>hasPrerelease(c.version)&&
        c.version.major===v.major&&c.version.minor===v.minor&&c.version.patch===v.patch);
      if(!same)continue;
    }
    return true;
  }
  return false;
}

function runCli(){
  const args=process.argv.slice(2);
  if(args.length!==1){
    process.stderr.write('usage: node semver-range.js INPUT_JSON_FILE\n');
    process.exit(2);
  }
  let raw;
  try{raw=fs.readFileSync(args[0],'utf8');}catch{
    process.stderr.write('cannot read input file\n');
    process.exit(2);
  }
  let data;
  try{data=JSON.parse(raw);}catch{
    process.stderr.write('invalid JSON\n');
    process.exit(2);
  }
  if(data===null||Array.isArray(data)||typeof data!=='object'){
    process.stderr.write('input must be an object\n');
    process.exit(2);
  }
  if(!Array.isArray(data.versions)||!data.versions.every(x=>typeof x==='string')){
    process.stderr.write('versions must be an array of strings\n');
    process.exit(2);
  }
  if(typeof data.range!=='string'){
    process.stderr.write('range must be a string\n');
    process.exit(2);
  }
  let sorted,satisfying;
  try{
    sorted=data.versions.map((v,i)=>({v,i})).sort((a,b)=>{
      const d=compareVersions(a.v,b.v);
      return d!==0?d:a.i-b.i;
    }).map(x=>x.v);
    satisfying=sorted.filter(v=>satisfies(v,data.range));
  }catch(err){
    process.stderr.write(String(err&&err.message||err)+'\n');
    process.exit(2);
  }
  process.stdout.write(JSON.stringify({sorted,satisfying})+'\n');
  process.exit(0);
}

import fs from 'node:fs';
if(process.argv[1]&&import.meta.url===`file://${process.argv[1]}`)runCli();

