import assert from 'node:assert/strict';
import {spawnSync} from 'node:child_process';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';

const entry = new URL('./semver-range.js', import.meta.url).pathname;
const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'semver-cli-'));

function run(args) {
  return spawnSync(process.execPath, [entry, ...args], {encoding: 'utf8', timeout: 5000, killSignal: 'SIGKILL'});
}

function writeFile(name, content) {
  const p = path.join(tmp, name);
  fs.writeFileSync(p, content);
  return p;
}

// valid case: sorted + satisfying
{
  const f = writeFile('ok.json', JSON.stringify({versions: ['1.0.0', '1.0.0', '2.0.0', '1.0.0-rc'], range: '>=1.0.0 <2.0.0'}));
  const r = run([f]);
  assert.equal(r.status, 0, r.stderr);
  assert.equal(r.stderr, '');
  assert.deepEqual(JSON.parse(r.stdout), {sorted: ['1.0.0-rc', '1.0.0', '1.0.0', '2.0.0'], satisfying: ['1.0.0', '1.0.0']});
  assert.ok(r.stdout.endsWith('\n'));
}

// no args → exit 2, nonempty stderr, no stdout
{
  const r = run([]);
  assert.equal(r.status, 2, r.stderr);
  assert.ok(r.stderr.length > 0);
  assert.equal(r.stdout, '');
}

// missing file → exit 2
{
  const r = run([path.join(tmp, 'nope.json')]);
  assert.equal(r.status, 2, r.stderr);
  assert.ok(r.stderr.length > 0);
  assert.equal(r.stdout, '');
}

// invalid JSON → exit 2
{
  const f = writeFile('bad.json', 'not json');
  const r = run([f]);
  assert.equal(r.status, 2, r.stderr);
  assert.ok(r.stderr.length > 0);
  assert.equal(r.stdout, '');
}

// invalid range → exit 2
{
  const f = writeFile('badrange.json', JSON.stringify({versions: [], range: ''}));
  const r = run([f]);
  assert.equal(r.status, 2, r.stderr);
  assert.ok(r.stderr.length > 0);
  assert.equal(r.stdout, '');
}

// empty versions, valid range → exit 0
{
  const f = writeFile('empty.json', JSON.stringify({versions: [], range: '>=1.0.0'}));
  const r = run([f]);
  assert.equal(r.status, 0, r.stderr);
  assert.equal(r.stderr, '');
  assert.deepEqual(JSON.parse(r.stdout), {sorted: [], satisfying: []});
}

// extra fields ignored
{
  const f = writeFile('extra.json', JSON.stringify({versions: ['1.0.0'], range: '1.0.0', foo: 'bar'}));
  const r = run([f]);
  assert.equal(r.status, 0, r.stderr);
  assert.deepEqual(JSON.parse(r.stdout), {sorted: ['1.0.0'], satisfying: ['1.0.0']});
}

// null / array → exit 2
for (const bad of ['null', '[1,2]']) {
  const f = writeFile('badtype.json', bad);
  const r = run([f]);
  assert.equal(r.status, 2, r.stderr);
  assert.ok(r.stderr.length > 0);
  assert.equal(r.stdout, '');
}

fs.rmSync(tmp, {recursive: true, force: true});
console.log('ALL CLI CHECKS PASSED');

